C_KZG_RET bytes_to_bls_field(fr_t *out, const Bytes32 *b) {
    blst_scalar tmp;
    blst_scalar_from_bendian(&tmp, b->bytes);  // big-endian deserialization
    if (!blst_scalar_fr_check(&tmp)) return C_KZG_BADARGS;  // RANGE CHECK vs BLS_MODULUS
    blst_fr_from_scalar(out, &tmp);
    return C_KZG_OK;
}

